      T.eq('a τ⁻¹ᐟ² law recovers −0.5 — the benign case the inequality could not separate', slopeOf(-0.5), -0.5);
      T.eq('a τ⁰ law recovers 0 — a floor, where more averaging buys nothing', slopeOf(0), 0);
