      T.ok('…and none of them is NaN (the shape JSON.stringify would have hidden)', z && !Number.isNaN(z.lfhf) && !Number.isNaN(z.lfnu) && !Number.isNaN(z.hfnu), 'lfhf=' + (z && String(z.lfhf)));

