      var hfnu = s && (s.hf == null || s.lf == null ? null : +((s.hf / (s.hf + s.lf || 1)) * 100).toFixed(1));
      T.eq('hfnu is null, NOT the 0.0 % the `|| 1` used to publish', hfnu, null);

