          Mode: sig([1, 0, 7], 1), // APAP, CPAP, unknown-code
          RIN: sig([2.5, 0, 4.1], 1),
          CSR: sig([3.0, 0, 12.4], 1),
          'S.EPR.Level': sig([3, 3, 3], 1),
