        hypoxicBurden: blk(3.2, 21, 5.5),
        motionProfile: blk(4.3, 23, 6.6),
        sleepStability: blk(5.4, 25, 7.7),
        sleepQuality: blk(6.5, 27, 8.8),
        desatProfile: blk(7.6, 29, 9.9),
