      T.eq('GATED ODI-3 count keeps only the real desats (the fix)', gat3, N_REAL);
      T.eq('the ODI-3 exclusion count equals the ODI-4 exclusion count — the SAME artifacts', ung3 - gat3, ung4 - gat4);
