          p2(d2.getUTCMonth() + 1) +
          '-' +
          p2(d2.getUTCDate()) +
          'T' +
          p2(d2.getUTCHours()) +
          ':' +
          p2(d2.getUTCMinutes()) +
          ':' +
          p2(d2.getUTCSeconds()) +
          '.' +
          ('00' + d2.getUTCMilliseconds()).slice(-3);
