          '-' +
          p2(d.getUTCMonth() + 1) +
          '-' +
          p2(d.getUTCDate()) +
          'T' +
          p2(d.getUTCHours()) +
          ':' +
          p2(d.getUTCMinutes()) +
          ':' +
          p2(d.getUTCSeconds()) +
          '.' +
          String(d.getUTCMilliseconds()).padStart(3, '0');
